        self.active_sessions[session_id]['last_activity'] = time.time()

    def is_session_expired(self, session_id):
        if session_id in self.active_sessions:
            last_activity = self.active_sessions[session_id]['last_activity']
            time_since_last_activity = time.time() - last_activity
            return time_since_last_activity >= self.inactivity_timeout
